const blankUseCase = { code: '', name: '', scope: '', level: 'User-goal', stakeholders: '', specialRequirements: '', summary: '', actor: '', trigger: '', preconditions: '', mainFlow: '', alternateFlows: '', exceptionFlows: '', postconditions: '', businessRules: '', assumptions: '', dependencies: '', risk: 'High' }
const emptyProfile = () => ({ name: '', environment: '', baseUrl: '', allowedHosts: '', roles: 'Customer | /login | customer-e2e', testData: '{\n  "seed": "e2e"\n}', seedUrl: '', cleanupUrl: '' })
const statusTone = { Draft: 'slate', PendingApproval: 'amber', Approved: 'green', Rejected: 'red', Ready: 'green' }
const lines = (value) => String(value || '').split('\n').map((item) => item.trim()).filter(Boolean)
const profileToForm = (item) => ({ name: item?.name || '', environment: item?.environment?._id || item?.environment || '', baseUrl: item?.baseUrl || '', allowedHosts: (item?.allowedHosts || []).join('\n'), roles: (item?.roles || []).map((role) => `${role.name || ''} | ${role.loginUrl || ''} | ${role.credentialSecretRef || ''}`).join('\n'), testData: JSON.stringify(item?.testData || {}, null, 2), seedUrl: item?.hooks?.seedUrl || '', cleanupUrl: item?.hooks?.cleanupUrl || '' })

export default function E2EStudioPage() {
  const qc = useQueryClient(); const [search] = useSearchParams(); const user = useAuthStore((state) => state.user)
  const [project, setProject] = useState(''); const [activeStep, setActiveStep] = useState('profile'); const [profile, setProfile] = useState(emptyProfile); const [profileEditor, setProfileEditor] = useState('create'); const [profileMode, setProfileMode] = useState('SystemProfile'); const [selectedProfile, setSelectedProfile] = useState(''); const [useCase, setUseCase] = useState(blankUseCase); const [caseTarget, setCaseTarget] = useState({ useCaseId: '', storyId: '', suiteId: '' }); const [git, setGit] = useState({ integrationId: '', repository: '', ref: 'main', commitSha: '', pullRequestNumber: '', paths: 'README.md\npackage.json' })
  const projects = useQuery({ queryKey: ['projects'], queryFn: workspaceApi.projects }); const requestedEnvironment = search.get('environment') || ''; const activeProject = project || search.get('project') || projects.data?.[0]?._id || ''
  const environments = useQuery({ queryKey: ['e2e-environments', activeProject], queryFn: () => automationLabApi.environments(activeProject), enabled: Boolean(activeProject) }); const integrations = useQuery({ queryKey: ['integrations', activeProject], queryFn: () => workspaceApi.integrations(activeProject), enabled: Boolean(activeProject) }); const profiles = useQuery({ queryKey: ['system-profiles', activeProject], queryFn: () => e2eApi.profiles(activeProject), enabled: Boolean(activeProject) })
  const currentProfile = (profiles.data || []).find((item) => item._id === selectedProfile) || (profiles.data || [])[0]; const useCases = useQuery({ queryKey: ['use-cases', activeProject, currentProfile?._id], queryFn: () => e2eApi.useCases(activeProject, currentProfile?._id), enabled: Boolean(activeProject && currentProfile?._id) }); const stories = useQuery({ queryKey: ['e2e-stories', activeProject], queryFn: () => catalogApi.stories(activeProject), enabled: Boolean(activeProject) }); const suites = useQuery({ queryKey: ['e2e-suites', activeProject], queryFn: () => catalogApi.suites(activeProject), enabled: Boolean(activeProject) }); const members = useQuery({ queryKey: ['e2e-members', activeProject], queryFn: () => catalogApi.members(activeProject), enabled: Boolean(activeProject) }); const e2eCases = useQuery({ queryKey: ['e2e-cases', activeProject], queryFn: () => testCaseApi.list(`project=${activeProject}&limit=100`), enabled: Boolean(activeProject) }); const plans = useQuery({ queryKey: ['e2e-plans', activeProject], queryFn: () => executionApi.plans(activeProject), enabled: Boolean(activeProject) })
  const github = useMemo(() => (integrations.data || []).filter((item) => item.provider === 'GitHub' && item.status === 'Connected'), [integrations.data]); const currentCases = (e2eCases.data || []).filter((item) => item.generatedFrom === 'SystemE2E' && String(item.e2e?.systemProfile?._id || item.e2e?.systemProfile || '') === String(currentProfile?._id || '')); const currentStories = (stories.data || []).filter((item) => String(item.e2e?.systemProfile?._id || item.e2e?.systemProfile || '') === String(currentProfile?._id || '')); const reviewers = (members.data || []).filter((item) => item.role?.permissions?.includes('testcase:approve') && item._id !== user?._id)
  useEffect(() => { if (requestedEnvironment) setProfile((current) => current.environment ? current : { ...current, environment: requestedEnvironment }) }, [requestedEnvironment])
  const refreshProfiles = () => qc.invalidateQueries({ queryKey: ['system-profiles', activeProject] }); const serialiseProfile = () => { let testData = {}; try { testData = JSON.parse(profile.testData || '{}') } catch { throw new Error('Test data phải là JSON hợp lệ.') }; return { name: profile.name, environment: profile.environment || null, baseUrl: profile.baseUrl, allowedHosts: lines(profile.allowedHosts), roles: lines(profile.roles).map((line) => { const [name, loginUrl, credentialSecretRef] = line.split('|').map((item) => item.trim()); return { name, loginUrl, credentialSecretRef, startState: 'authenticated' } }), testData, hooks: { seedUrl: profile.seedUrl.trim(), cleanupUrl: profile.cleanupUrl.trim() } } }
  const createProfile = useMutation({ mutationFn: () => e2eApi.createProfile({ project: activeProject, mode: profileMode, ...serialiseProfile() }), onSuccess: (result) => { toast.success('Đã lưu System Profile'); setSelectedProfile(result._id); setProfileEditor('edit'); refreshProfiles() }, onError: (error) => toast.error(error.message) }); const updateProfile = useMutation({ mutationFn: () => e2eApi.updateProfile(currentProfile._id, { ...serialiseProfile(), status: 'Ready' }), onSuccess: (result) => { toast.success('Đã cập nhật System Profile'); setSelectedProfile(result._id); setProfileEditor('edit'); refreshProfiles() }, onError: (error) => toast.error(error.message) }); const analyzeGithub = useMutation({ mutationFn: () => e2eApi.analyzeGithub({ projectId: activeProject, name: profile.name || `GitHub E2E · ${git.repository}`, environment: profile.environment || null, ...git, pullRequestNumber: git.pullRequestNumber ? Number(git.pullRequestNumber) : null, paths: lines(git.paths) }), onSuccess: (result) => { toast.success('Đã tạo System Specification từ GitHub'); setSelectedProfile(result.profile._id); setProfileEditor('edit'); refreshProfiles() }, onError: (error) => toast.error(error.message) })
  const suggestUseCases = useMutation({ mutationFn: () => e2eApi.suggestUseCases(currentProfile._id), onSuccess: (result) => { toast.success(result._e2eFallback ? `Gemini đã hết quota: đã tạo ${result.length} Use Case E2E nháp theo Profile` : `Gemini đã tạo ${result.length} Use Case nháp`); qc.invalidateQueries({ queryKey: ['use-cases'] }) }, onError: (error) => toast.error(error.message) }); const addUseCase = useMutation({ mutationFn: () => e2eApi.createUseCase({ ...blankUseCase, ...useCase, systemProfile: currentProfile._id, stakeholders: lines(useCase.stakeholders), specialRequirements: lines(useCase.specialRequirements), preconditions: lines(useCase.preconditions), mainFlow: lines(useCase.mainFlow), alternateFlows: lines(useCase.alternateFlows), exceptionFlows: lines(useCase.exceptionFlows), postconditions: lines(useCase.postconditions), businessRules: lines(useCase.businessRules), assumptions: lines(useCase.assumptions), dependencies: lines(useCase.dependencies) }), onSuccess: () => { toast.success('Đã thêm Use Case chuẩn'); setUseCase(blankUseCase); qc.invalidateQueries({ queryKey: ['use-cases'] }) }, onError: (error) => toast.error(error.message) }); const approveUseCase = useMutation({ mutationFn: (id) => e2eApi.decideUseCase(id, { decision: 'Approved', reviewNote: 'Use Case E2E đã được QA Manager duyệt.' }), onSuccess: () => { toast.success('Đã duyệt Use Case'); qc.invalidateQueries({ queryKey: ['use-cases'] }) }, onError: (error) => toast.error(error.message) }); const generateStory = useMutation({ mutationFn: e2eApi.generateStory, onSuccess: (result) => { toast.success(result._e2eFallback ? 'Gemini đã hết quota: đã tạo User Story E2E nháp' : 'Gemini đã tạo User Story E2E nháp để bạn chỉnh sửa'); setActiveStep('story'); qc.invalidateQueries({ queryKey: ['e2e-stories'] }) }, onError: (error) => toast.error(error.message) }); const updateStory = useMutation({ mutationFn: ({ id, body }) => requirementApi.updateStory(id, body), onSuccess: () => { toast.success('Đã lưu bản nháp User Story'); qc.invalidateQueries({ queryKey: ['e2e-stories'] }) }, onError: (error) => toast.error(error.message) }); const submitStory = useMutation({ mutationFn: async ({ id, body }) => { await requirementApi.updateStory(id, body); return requirementApi.submitApproval(id) }, onSuccess: () => { toast.success('Đã gửi User Story cho QA Manager duyệt'); qc.invalidateQueries({ queryKey: ['e2e-stories'] }) }, onError: (error) => toast.error(error.message) }); const reviseStory = useMutation({ mutationFn: (story) => requirementApi.createStory({ project: story.project?._id || story.project, title: story.title, description: story.description, acceptanceCriteria: (story.acceptanceCriteria || []).map((item) => ({ criteria: item.criteria || item, isCompleted: false })), priority: story.priority || 'Medium', storyPoints: story.storyPoints || 0, source: 'AI', approvalStatus: 'Draft', aiSuggestion: story.aiSuggestion || null, e2e: story.e2e || {} }), onSuccess: () => { toast.success('Đã tạo bản nháp để chỉnh sửa và gửi duyệt lại'); qc.invalidateQueries({ queryKey: ['e2e-stories'] }) }, onError: (error) => toast.error(error.message) })
  const createSuite = useMutation({ mutationFn: () => testSuiteApi.create({ project: activeProject, name: `E2E · ${currentProfile?.name || 'System journey'}`, description: 'Test Suite tự tạo cho các E2E journey trong System Profile.' }), onSuccess: (result) => { setCaseTarget((item) => ({ ...item, suiteId: result._id })); toast.success('Đã tạo Test Suite E2E'); qc.invalidateQueries({ queryKey: ['e2e-suites'] }) }, onError: (error) => toast.error(error.message) }); const generateCases = useMutation({ mutationFn: () => e2eApi.generateCases(caseTarget.useCaseId, { userStoryId: caseTarget.storyId, testSuiteId: caseTarget.suiteId }), onSuccess: (result) => { toast.success(result._e2eFallback ? `Gemini đã hết quota: đã tạo ${result.length} Test Case E2E nháp` : `Gemini đã tạo ${result.length} E2E Test Case Draft`); qc.invalidateQueries({ queryKey: ['e2e-cases'] }) }, onError: (error) => toast.error(error.message) }); const editCase = useMutation({ mutationFn: ({ id, body }) => testCaseApi.update(id, body), onSuccess: () => qc.invalidateQueries({ queryKey: ['e2e-cases'] }), onError: (error) => toast.error(error.message) }); const submitCase = useMutation({ mutationFn: ({ id, body }) => testCaseApi.submitReview(id, body), onSuccess: () => { toast.success('Đã gửi Test Case cho QA Manager'); qc.invalidateQueries({ queryKey: ['e2e-cases'] }) }, onError: (error) => toast.error(error.message) }); const suggestPlan = useMutation({ mutationFn: () => executionApi.suggestPlan({ project: activeProject, testCaseIds: currentCases.filter((item) => item.status === 'Approved').map((item) => item._id), environment: currentProfile?.baseUrl || 'Staging' }), onSuccess: () => { toast.success('Đã tạo Test Plan E2E'); qc.invalidateQueries({ queryKey: ['e2e-plans'] }) }, onError: (error) => toast.error(error.message) }); const approvePlan = useMutation({ mutationFn: (id) => executionApi.decidePlan(id, { decision: 'Approved', reviewNote: 'Test Plan E2E đã được QA Manager duyệt.' }), onSuccess: () => { toast.success('Đã duyệt Test Plan E2E'); qc.invalidateQueries({ queryKey: ['e2e-plans'] }) }, onError: (error) => toast.error(error.message) })
  const download = async (request, fileName) => { try { const response = await request(); const isTestCaseExport = response.config?.url?.includes('/e2e-artifacts/test-case/'); const outputFileName = isTestCaseExport ? fileName.replace(/\.docx?$/i, '.xls') : fileName; const url = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = url; link.download = outputFileName; link.click(); URL.revokeObjectURL(url) } catch (error) { toast.error(error.message || 'Không thể xuất tài liệu.') } }; const newProfile = () => { setSelectedProfile(''); setProfileEditor('create'); setProfileMode('SystemProfile'); setProfile(emptyProfile()) }; const selectProfile = (id) => { const item = (profiles.data || []).find((profileItem) => profileItem._id === id); if (!item) return newProfile(); setSelectedProfile(id); setProfileEditor('edit'); setProfileMode(item.mode || 'SystemProfile'); setProfile(profileToForm(item)) }
  const _storyRevision = reviseStory
  return <QAWorkflow {...{ activeProject, activeStep, setActiveStep, projects, project, setProject, currentProfile, profiles, profile, setProfile, profileEditor, profileMode, setProfileMode, environments, github, git, setGit, createProfile, updateProfile, analyzeGithub, newProfile, selectProfile, useCases, useCase, setUseCase, suggestUseCases, addUseCase, approveUseCase, generateStory, currentStories, user, updateStory, submitStory, suites, caseTarget, setCaseTarget, createSuite, generateCases, currentCases, reviewers, editCase, submitCase, plans, download }} />
  const steps = [{ id: 'profile', label: 'Profile', icon: Layers3, done: Boolean(currentProfile) }, { id: 'usecase', label: 'Hành trình', icon: Route, done: (useCases.data || []).some((item) => item.status === 'Approved') }, { id: 'story', label: 'Yêu cầu', icon: FileText, done: currentStories.some((item) => item.approvalStatus === 'Approved') }, { id: 'testcase', label: 'Kiểm thử', icon: ClipboardCheck, done: currentCases.some((item) => item.status === 'Approved') }, { id: 'plan', label: 'Kế hoạch', icon: FileCheck2, done: (plans.data || []).some((item) => item.approvalStatus === 'Approved') }, { id: 'run', label: 'Chạy & báo cáo', icon: PlayCircle, done: false }]; const activeIndex = steps.findIndex((step) => step.id === activeStep)
  return <div className="space-y-5 pb-8"><E2EVisualHero /><PageHeader eyebrow="E2E workspace" title="Thiết kế hành trình kiểm thử" description="Một luồng rõ ràng từ ngữ cảnh hệ thống đến lần chạy cuối cùng." actions={<Button variant="outline" asChild><Link to="/automation"><TestTube2 className="h-4 w-4" />Automation Lab</Link></Button>} /><Card className="overflow-hidden border-slate-200 shadow-sm dark:border-slate-800"><div className="flex flex-col gap-4 bg-gradient-to-r from-violet-50 via-white to-sky-50 p-4 dark:from-violet-950/30 dark:via-[#17181d] dark:to-slate-900 sm:flex-row sm:items-end sm:justify-between"><div className="w-full sm:max-w-sm"><label className="label">Không gian làm việc</label><Select value={activeProject} onChange={(event) => { setProject(event.target.value); newProfile(); setActiveStep('profile') }}><option value="">Chọn Project</option>{(projects.data || []).map((item) => <option key={item._id} value={item._id}>{item.key} · {item.name}</option>)}</Select></div><div className="rounded-xl border border-white/80 bg-white/80 px-3 py-2 text-xs text-slate-600 shadow-sm dark:border-slate-700 dark:bg-slate-900/80 dark:text-slate-300"><span className="font-semibold text-slate-900 dark:text-white">{currentProfile?.name || 'Chưa chọn System Profile'}</span><span className="mx-2 text-slate-300">/</span>{activeIndex + 1} trên {steps.length}</div></div><nav className="flex overflow-x-auto border-t border-slate-100 px-2 py-2 dark:border-slate-800">{steps.map((step, index) => { const active = step.id === activeStep; return <button key={step.id} type="button" onClick={() => setActiveStep(step.id)} className={`group flex min-w-[118px] flex-1 items-center gap-2 rounded-lg px-3 py-2.5 text-left transition ${active ? 'bg-violet-600 text-white shadow-sm' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-white'}`}><span className={`grid h-6 w-6 shrink-0 place-items-center rounded-full text-[10px] font-bold ${active ? 'bg-white/20' : step.done ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300' : 'bg-slate-100 text-slate-500 dark:bg-slate-800'}`}>{step.done && !active ? <Check className="h-3.5 w-3.5" /> : index + 1}</span><span className="min-w-0"><span className="block truncate text-xs font-semibold">{step.label}</span><span className={`block text-[10px] ${active ? 'text-violet-100' : 'text-slate-400'}`}>{step.done ? 'Hoàn tất' : 'Tiếp theo'}</span></span></button>})}</nav></Card>{activeStep === 'profile' && <ProfileStep {...{ activeProject, profiles, currentProfile, profile, setProfile, profileEditor, profileMode, setProfileMode, environments, github, git, setGit, createProfile, updateProfile, analyzeGithub, newProfile, selectProfile }} />}{activeStep === 'usecase' && <JourneyStep {...{ currentProfile, profiles, useCases, useCase, setUseCase, suggestUseCases, addUseCase, approveUseCase, generateStory, selectProfile, download }} />}{activeStep === 'story' && <StoryStep {...{ currentProfile, currentStories, user, updateStory, submitStory, download, setActiveStep }} />}{activeStep === 'testcase' && <TestCaseStep {...{ currentProfile, useCases, currentStories, suites, caseTarget, setCaseTarget, createSuite, generateCases, currentCases, reviewers, user, editCase, submitCase, download }} />}{activeStep === 'plan' && <PlanStep {...{ currentCases, plans, suggestPlan, approvePlan, download }} />}{activeStep === 'run' && <RunStep activeProject={activeProject} plans={plans.data || []} />}</div>
}

function ProfileStep({ activeProject, profiles, currentProfile, profile, setProfile, profileEditor, profileMode, setProfileMode, environments, github, git, setGit, createProfile, updateProfile, analyzeGithub, newProfile, selectProfile }) { const update = (key, value) => setProfile({ ...profile, [key]: value }); const isGitHub = profileMode === 'GitHubE2E'; return <Card className="overflow-hidden"><div className="flex flex-col gap-3 border-b p-5 sm:flex-row sm:items-center sm:justify-between"><SectionTitle title="Điểm bắt đầu" description="Xác định hệ thống và môi trường trước khi thiết kế hành trình." /><Button variant="outline" onClick={newProfile}><Plus className="h-4 w-4" />Profile mới</Button></div><div className="grid gap-6 p-5 xl:grid-cols-[260px_1fr]"><aside className="space-y-2"><p className="text-xs font-semibold uppercase tracking-wide text-slate-400">System Profile</p><Select value={profileEditor === 'edit' ? currentProfile?._id || '' : ''} onChange={(event) => selectProfile(event.target.value)}><option value="">Tạo System Profile mới</option>{(profiles.data || []).map((item) => <option key={item._id} value={item._id}>{item.name}</option>)}</Select><div className="rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-500 dark:bg-slate-900">Lưu profile một lần, các bước sau tự động dùng chung ngữ cảnh này.</div></aside><div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2"><ModeOption active={!isGitHub} disabled={profileEditor === 'edit'} icon={Layers3} title="Khai báo thủ công" description="Nhập hệ thống, role và môi trường." onClick={() => setProfileMode('SystemProfile')} /><ModeOption active={isGitHub} disabled={profileEditor === 'edit'} icon={GitBranch} title="Phân tích GitHub" description="Tạo specification từ nguồn đã chọn." onClick={() => setProfileMode('GitHubE2E')} /></div><div className="grid gap-3 md:grid-cols-2"><Field label="Tên System Profile" required><Input value={profile.name} onChange={(event) => update('name', event.target.value)} placeholder="Checkout · Release 1.2" /></Field><Field label="Environment"><Select value={profile.environment} onChange={(event) => update('environment', event.target.value)}><option value="">Chọn sau / dùng URL</option>{(environments.data || []).filter((item) => item.status === 'Ready').map((item) => <option key={item._id} value={item._id}>{item.name} · {item.targetUrl}</option>)}</Select></Field></div>{isGitHub ? <GitHubForm {...{ github, git, setGit, analyzeGithub, activeProject, profile }} /> : <><div className="grid gap-3 md:grid-cols-2"><Field label="Base URL" required><Input value={profile.baseUrl} onChange={(event) => update('baseUrl', event.target.value)} placeholder="https://staging.example.com" /></Field><Field label="Allowed hosts"><Input value={profile.allowedHosts} onChange={(event) => update('allowedHosts', event.target.value)} placeholder="api.example.com, mỗi dòng một host" /></Field></div><details className="group rounded-xl border border-slate-200 p-4 dark:border-slate-700"><summary className="flex cursor-pointer list-none items-center justify-between text-sm font-medium">Thiết lập nâng cao <Settings2 className="h-4 w-4 text-slate-400 transition group-open:rotate-90" /></summary><div className="mt-4 grid gap-3 md:grid-cols-2"><Field label="Role | login URL | secret ref"><Textarea value={profile.roles} onChange={(event) => update('roles', event.target.value)} className="min-h-28 font-mono text-xs" /></Field><Field label="Test data (JSON)"><Textarea value={profile.testData} onChange={(event) => update('testData', event.target.value)} className="min-h-28 font-mono text-xs" /></Field><Field label="Seed hook"><Input value={profile.seedUrl} onChange={(event) => update('seedUrl', event.target.value)} /></Field><Field label="Cleanup hook"><Input value={profile.cleanupUrl} onChange={(event) => update('cleanupUrl', event.target.value)} /></Field></div></details><Button disabled={!activeProject || !profile.name || !profile.baseUrl || createProfile.isPending || updateProfile.isPending} onClick={() => profileEditor === 'edit' ? updateProfile.mutate() : createProfile.mutate()}><CheckCircle2 className="h-4 w-4" />{profileEditor === 'edit' ? 'Lưu thay đổi' : 'Lưu System Profile'}</Button></>}</div></div></Card> }
function JourneyStep({ currentProfile, profiles, useCases, useCase, setUseCase, suggestUseCases, addUseCase, approveUseCase, generateStory, selectProfile, download }) {
  if (!currentProfile) return <ProfileRequired profiles={profiles} selectProfile={selectProfile} />
  const update = (key, value) => setUseCase({ ...useCase, [key]: value })
  return <AcademicJourneyWorkspace {...{ currentProfile, useCases, useCase, update, suggestUseCases, addUseCase, approveUseCase, generateStory, download }} />
  return <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_300px]"><Card className="p-5"><SectionTitle title="Hành trình nghiệp vụ" description="Use Case E2E theo cấu trúc chuẩn: mục tiêu, tác nhân, điều kiện, luồng, ngoại lệ, hậu điều kiện và ràng buộc." action={<Button size="sm" onClick={() => suggestUseCases.mutate()} disabled={suggestUseCases.isPending}><Sparkles className="h-3.5 w-3.5" />Đề xuất bằng AI</Button>} /><div className="mt-5 rounded-xl border border-dashed border-violet-200 bg-violet-50/40 p-4 dark:border-violet-900 dark:bg-violet-950/20"><div className="grid gap-3 md:grid-cols-2"><Field label="Tên Use Case" required><Input value={useCase.name} onChange={(event) => update('name', event.target.value)} placeholder="Sinh viên nộp bài tập" /></Field><Field label="Actor / tác nhân" required><Input value={useCase.actor} onChange={(event) => update('actor', event.target.value)} placeholder="Sinh viên" /></Field><Field label="Mã Use Case"><Input value={useCase.code} onChange={(event) => update('code', event.target.value)} placeholder="UC-OOP-01" /></Field><Field label="Mức rủi ro"><Select value={useCase.risk} onChange={(event) => update('risk', event.target.value)}>{['Critical', 'High', 'Medium', 'Low'].map((item) => <option key={item}>{item}</option>)}</Select></Field></div><div className="mt-3 grid gap-3"><Field label="Mục tiêu / giá trị nghiệp vụ" required><Textarea value={useCase.summary} onChange={(event) => update('summary', event.target.value)} placeholder="Giá trị nghiệp vụ cần bảo vệ và kết quả cuối cùng cần đạt." /></Field><Field label="Sự kiện kích hoạt"><Input value={useCase.trigger} onChange={(event) => update('trigger', event.target.value)} placeholder="Sinh viên chọn nộp bài tập trong khóa học." /></Field><Field label="Luồng chính · mỗi dòng một bước" required><Textarea className="min-h-28" value={useCase.mainFlow} onChange={(event) => update('mainFlow', event.target.value)} placeholder={'Đăng nhập\nMở khóa học OOP\nChọn bài tập\nTải tệp và nộp bài\nXác nhận trạng thái nộp bài'} /></Field></div><details className="group mt-3 rounded-xl border border-slate-200 bg-white/60 p-4 dark:border-slate-700 dark:bg-slate-900/40"><summary className="cursor-pointer text-sm font-semibold">Thành phần Use Case chuẩn · mở để khai báo đầy đủ</summary><p className="mt-1 text-xs text-slate-500">Mỗi dòng là một mục để xuất tài liệu và sinh E2E Test Case có cấu trúc rõ ràng.</p><div className="mt-4 grid gap-3 md:grid-cols-2"><Field label="Tiền điều kiện"><Textarea value={useCase.preconditions} onChange={(event) => update('preconditions', event.target.value)} placeholder="Đã đăng nhập\nĐã ghi danh khóa học OOP" /></Field><Field label="Hậu điều kiện"><Textarea value={useCase.postconditions} onChange={(event) => update('postconditions', event.target.value)} placeholder="Bài nộp được lưu\nTrạng thái hiển thị chính xác" /></Field><Field label="Luồng thay thế"><Textarea value={useCase.alternateFlows} onChange={(event) => update('alternateFlows', event.target.value)} placeholder="Lưu nháp khi chưa nộp\nThay tệp trước thời hạn" /></Field><Field label="Luồng lỗi / recovery"><Textarea value={useCase.exceptionFlows} onChange={(event) => update('exceptionFlows', event.target.value)} placeholder="Tệp không hợp lệ: báo lỗi\nPhiên hết hạn: yêu cầu đăng nhập lại" /></Field><Field label="Quy tắc nghiệp vụ"><Textarea value={useCase.businessRules} onChange={(event) => update('businessRules', event.target.value)} placeholder="Chỉ được nộp trước hạn\nChỉ sinh viên đã ghi danh được nộp" /></Field><Field label="Giả định"><Textarea value={useCase.assumptions} onChange={(event) => update('assumptions', event.target.value)} placeholder="Tài khoản và dữ liệu E2E đã được cấp" /></Field><Field label="Phụ thuộc / tích hợp"><Textarea value={useCase.dependencies} onChange={(event) => update('dependencies', event.target.value)} placeholder="Xác thực\nLưu trữ tệp\nDịch vụ khóa học" /></Field></div></details><Button className="mt-3" variant="outline" disabled={!useCase.name || !useCase.actor || !useCase.summary || !lines(useCase.mainFlow).length || addUseCase.isPending} onClick={() => addUseCase.mutate()}><Plus className="h-4 w-4" />Thêm Use Case</Button></div><div className="mt-5 space-y-3">{(useCases.data || []).map((item) => <article key={item._id} className="rounded-xl border p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><div className="flex gap-2"><Badge tone={statusTone[item.status]}>{item.status}</Badge><Badge tone="purple">{item.risk}</Badge><span className="text-xs text-slate-400">{item.code}</span></div><p className="mt-2 text-sm font-semibold">{item.name}</p><p className="mt-1 text-xs text-slate-500">Actor: {item.actor} · {item.mainFlow?.length || 0} bước chính · {item.exceptionFlows?.length || 0} ngoại lệ</p></div><div className="flex shrink-0 flex-wrap gap-2">{item.status !== 'Approved' ? <Button size="sm" onClick={() => approveUseCase.mutate(item._id)} disabled={approveUseCase.isPending}><Check className="h-3.5 w-3.5" />Duyệt</Button> : <Button size="sm" variant="outline" onClick={() => generateStory.mutate(item._id)} disabled={generateStory.isPending}><Bot className="h-3.5 w-3.5" />Sinh yêu cầu</Button>}<Button size="sm" variant="ghost" onClick={() => download(() => e2eApi.exportArtifact('use-case', item._id, 'doc'), `use-case-${item.code || item._id}.doc`)}><Download className="h-3.5 w-3.5" /></Button></div></div><details className="mt-3 rounded-lg bg-slate-50 p-3 text-xs leading-5 text-slate-600 dark:bg-slate-900 dark:text-slate-300"><summary className="cursor-pointer font-semibold">Xem Use Case đầy đủ</summary><UseCaseList label="Mục tiêu" value={item.summary ? [item.summary] : []} /><UseCaseList label="Kích hoạt" value={item.trigger ? [item.trigger] : []} /><UseCaseList label="Tiền điều kiện" value={item.preconditions} /><UseCaseList label="Luồng chính" value={item.mainFlow} /><UseCaseList label="Luồng thay thế" value={item.alternateFlows} /><UseCaseList label="Luồng lỗi / recovery" value={item.exceptionFlows} /><UseCaseList label="Hậu điều kiện" value={item.postconditions} /><UseCaseList label="Quy tắc nghiệp vụ" value={item.businessRules} /><UseCaseList label="Giả định" value={item.assumptions} /><UseCaseList label="Phụ thuộc / tích hợp" value={item.dependencies} /></details></article>)}{!(useCases.data || []).length && <p className="py-8 text-center text-sm text-slate-400">Chưa có hành trình nào.</p>}</div></Card><ContextCard profile={currentProfile} label="Hành trình" items={[["Đã tạo", useCases.data?.length || 0], ["Đã duyệt", (useCases.data || []).filter((item) => item.status === 'Approved').length], ["Roles", currentProfile.roles?.length || 0]]} /></div>
}
function UseCaseList({ label, value }) { const rows = Array.isArray(value) ? value.filter(Boolean) : []; return rows.length ? <div className="mt-3"><p className="font-semibold text-slate-700 dark:text-slate-200">{label}</p><ol className="mt-1 list-decimal space-y-0.5 pl-5">{rows.map((row, index) => <li key={index}>{row}</li>)}</ol></div> : null }
function AcademicJourneyWorkspace({ currentProfile, useCases, useCase, update, suggestUseCases, addUseCase, approveUseCase, generateStory, download }) {
  const textFields = [
    ['stakeholders', 'Các bên liên quan / lợi ích', 'Sinh viên: nộp bài đúng hạn\nGiảng viên: nhận bài để chấm'],
    ['specialRequirements', 'Yêu cầu đặc biệt', 'Tệp được quét an toàn\nPhản hồi dưới 3 giây'],
    ['preconditions', 'Tiền điều kiện', 'Đã đăng nhập\nĐã ghi danh khóa học OOP'],
    ['postconditions', 'Hậu điều kiện', 'Bài nộp được lưu\nTrạng thái được cập nhật'],
    ['alternateFlows', 'Luồng thay thế', 'Lưu nháp\nThay tệp trước hạn'],
    ['exceptionFlows', 'Luồng lỗi / recovery', 'Tệp không hợp lệ: báo lỗi\nPhiên hết hạn: yêu cầu đăng nhập lại'],
    ['businessRules', 'Quy tắc nghiệp vụ', 'Chỉ nộp trước hạn\nChỉ sinh viên đã ghi danh được nộp'],
    ['assumptions', 'Giả định', 'Tài khoản và dữ liệu E2E đã được cấp'],
    ['dependencies', 'Phụ thuộc / tích hợp', 'Xác thực\nLưu trữ tệp\nDịch vụ khóa học'],
  ]
  return <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_300px]"><Card className="p-5"><SectionTitle title="Hành trình nghiệp vụ" description="Use Case chuẩn phục vụ đặc tả, E2E test, truy vết và export." action={<Button size="sm" onClick={() => suggestUseCases.mutate()} disabled={suggestUseCases.isPending}><Sparkles className="h-3.5 w-3.5" />Đề xuất bằng AI</Button>} /><div className="mt-5 rounded-xl border border-dashed border-violet-200 bg-violet-50/40 p-4 dark:border-violet-900 dark:bg-violet-950/20"><div className="grid gap-3 md:grid-cols-2"><Field label="Tên Use Case" required><Input value={useCase.name} onChange={(event) => update('name', event.target.value)} /></Field><Field label="Actor / tác nhân chính" required><Input value={useCase.actor} onChange={(event) => update('actor', event.target.value)} /></Field><Field label="Mã Use Case"><Input value={useCase.code} onChange={(event) => update('code', event.target.value)} placeholder="UC-OOP-01" /></Field><Field label="Mức rủi ro"><Select value={useCase.risk} onChange={(event) => update('risk', event.target.value)}>{['Critical', 'High', 'Medium', 'Low'].map((item) => <option key={item}>{item}</option>)}</Select></Field><Field label="Phạm vi hệ thống"><Input value={useCase.scope} onChange={(event) => update('scope', event.target.value)} placeholder="e-Learning · Quản lý bài tập" /></Field><Field label="Cấp độ"><Select value={useCase.level} onChange={(event) => update('level', event.target.value)}>{['User-goal', 'Sub-function', 'Summary'].map((item) => <option key={item}>{item}</option>)}</Select></Field></div><div className="mt-3 grid gap-3"><Field label="Mục tiêu / giá trị nghiệp vụ" required><Textarea value={useCase.summary} onChange={(event) => update('summary', event.target.value)} /></Field><Field label="Sự kiện kích hoạt"><Input value={useCase.trigger} onChange={(event) => update('trigger', event.target.value)} /></Field><Field label="Luồng chính · mỗi dòng một bước" required><Textarea className="min-h-28" value={useCase.mainFlow} onChange={(event) => update('mainFlow', event.target.value)} /></Field></div><details className="group mt-3 rounded-xl border border-slate-200 bg-white/60 p-4 dark:border-slate-700 dark:bg-slate-900/40"><summary className="cursor-pointer text-sm font-semibold">Thành phần Use Case chuẩn · mở để khai báo đầy đủ</summary><p className="mt-1 text-xs text-slate-500">Các thành phần này được lưu riêng để đưa vào tài liệu và sinh test theo hành trình.</p><div className="mt-4 grid gap-3 md:grid-cols-2">{textFields.map(([key, label, placeholder]) => <Field key={key} label={label}><Textarea value={useCase[key] || ''} onChange={(event) => update(key, event.target.value)} placeholder={placeholder} /></Field>)}</div></details><Button className="mt-3" variant="outline" disabled={!useCase.name || !useCase.actor || !useCase.summary || !lines(useCase.mainFlow).length || addUseCase.isPending} onClick={() => addUseCase.mutate()}><Plus className="h-4 w-4" />Thêm Use Case chuẩn</Button></div><div className="mt-5 space-y-3">{(useCases.data || []).map((item) => <article key={item._id} className="rounded-xl border p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex flex-wrap gap-2"><Badge tone={statusTone[item.status]}>{item.status}</Badge><Badge tone="purple">{item.risk}</Badge><span className="text-xs text-slate-400">{item.code}</span></div><p className="mt-2 text-sm font-semibold">{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.scope || 'Chưa khai báo phạm vi'} · {item.level || 'User-goal'} · Actor: {item.actor}</p></div><div className="flex shrink-0 gap-2">{item.status !== 'Approved' ? <Button size="sm" onClick={() => approveUseCase.mutate(item._id)} disabled={approveUseCase.isPending}><Check className="h-3.5 w-3.5" />Duyệt</Button> : <Button size="sm" variant="outline" onClick={() => generateStory.mutate(item._id)} disabled={generateStory.isPending}><Bot className="h-3.5 w-3.5" />Sinh yêu cầu</Button>}<Button size="sm" variant="ghost" onClick={() => download(() => e2eApi.exportArtifact('use-case', item._id, 'doc'), `use-case-${item.code || item._id}.doc`)}><Download className="h-3.5 w-3.5" /></Button></div></div><details className="mt-3 rounded-lg bg-slate-50 p-3 text-xs leading-5 text-slate-600 dark:bg-slate-900 dark:text-slate-300"><summary className="cursor-pointer font-semibold">Xem Use Case đầy đủ</summary><UseCaseList label="Mục tiêu" value={item.summary ? [item.summary] : []} /><UseCaseList label="Kích hoạt" value={item.trigger ? [item.trigger] : []} /><UseCaseList label="Các bên liên quan / lợi ích" value={item.stakeholders} /><UseCaseList label="Tiền điều kiện" value={item.preconditions} /><UseCaseList label="Luồng chính" value={item.mainFlow} /><UseCaseList label="Luồng thay thế" value={item.alternateFlows} /><UseCaseList label="Luồng lỗi / recovery" value={item.exceptionFlows} /><UseCaseList label="Hậu điều kiện" value={item.postconditions} /><UseCaseList label="Quy tắc nghiệp vụ" value={item.businessRules} /><UseCaseList label="Yêu cầu đặc biệt" value={item.specialRequirements} /><UseCaseList label="Giả định" value={item.assumptions} /><UseCaseList label="Phụ thuộc / tích hợp" value={item.dependencies} /></details></article>)}{!(useCases.data || []).length && <p className="py-8 text-center text-sm text-slate-400">Chưa có Use Case nào.</p>}</div></Card><ContextCard profile={currentProfile} label="Hành trình" items={[["Đã tạo", useCases.data?.length || 0], ["Đã duyệt", (useCases.data || []).filter((item) => item.status === 'Approved').length], ["Roles", currentProfile.roles?.length || 0]]} /></div>
}
function StoryStep({ currentProfile, currentStories, user, updateStory, submitStory, download, setActiveStep }) {
  if (!currentProfile) return <ProfileRequired />
  const hasApprovedStory = currentStories.some((item) => item.approvalStatus === 'Approved')
  return <Card className="p-5"><SectionTitle title="Yêu cầu E2E" description="Gemini tạo bản nháp trước. Người yêu cầu sinh chỉnh sửa và chủ động gửi QA Manager duyệt." action={hasApprovedStory ? <Button size="sm" onClick={() => setActiveStep('testcase')}><ArrowRight className="h-3.5 w-3.5" />Tiếp tục: Sinh Test Case</Button> : null} /><div className="mt-5 space-y-3">{currentStories.map((item) => <StoryDraftCard key={`${item._id}-${item.updatedAt || ''}`} item={item} currentUser={user} updateStory={updateStory} submitStory={submitStory} download={download} />)}{!currentStories.length && <EmptyState title="Chưa có User Story" description="Duyệt một hành trình, rồi chọn “Sinh yêu cầu” ở bước Hành trình." />}{hasApprovedStory && <div className="flex justify-end border-t pt-4 dark:border-slate-800"><Button onClick={() => setActiveStep('testcase')}><ArrowRight className="h-4 w-4" />Tiếp tục: Sinh Test Case</Button></div>}</div></Card>
}
function StoryDraftCard({ item, currentUser, updateStory, submitStory, download }) {
  const [open, setOpen] = useState(false)
  const isOwner = String(item.createdBy?._id || item.createdBy || '') === String(currentUser?._id || '')
  // An approved AI story can be reopened by its requester.  Saving changes
  // returns it to Draft and sends it through QA approval again.
  const editable = ['Draft', 'Rejected', 'Approved'].includes(item.approvalStatus)
  const [draft, setDraft] = useState({ title: item.title || '', description: item.description || '', priority: item.priority || 'Medium', storyPoints: item.storyPoints || 0, acceptanceCriteria: (item.acceptanceCriteria || []).map((criterion) => criterion.criteria || '').filter(Boolean).join('\n') })
  const body = () => ({ title: draft.title.trim(), description: draft.description.trim(), priority: draft.priority, storyPoints: Number(draft.storyPoints) || 0, acceptanceCriteria: lines(draft.acceptanceCriteria).map((criteria) => ({ criteria, isCompleted: false })) })
  const invalid = !draft.title.trim() || !draft.description.trim() || !lines(draft.acceptanceCriteria).length
  return <><button type="button" onClick={() => setOpen(true)} className="block w-full rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-violet-300 hover:shadow-md dark:border-slate-700 dark:bg-slate-950/30"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex flex-wrap items-center gap-2"><Badge tone={statusTone[item.approvalStatus] || 'slate'}>{item.approvalStatus}</Badge>{item.source === 'AI' && <Badge tone="purple">AI suggestion</Badge>}</div><span className="text-xs font-semibold text-violet-600">Mở để xem / sửa</span></div><h3 className="mt-3 text-sm font-semibold">{item.title}</h3><p className="mt-1 line-clamp-2 text-sm leading-6 text-slate-500">{item.description}</p><div className="mt-3 rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-600 dark:bg-slate-900 dark:text-slate-300">{(item.acceptanceCriteria || []).slice(0, 2).map((criterion, index) => <p key={index}>AC {index + 1}: {criterion.criteria}</p>)}{(item.acceptanceCriteria || []).length > 2 && <p className="mt-1 text-slate-400">+ {(item.acceptanceCriteria || []).length - 2} tiêu chí khác</p>}</div></button><Dialog open={open} onOpenChange={setOpen} title={editable ? 'Chỉnh sửa User Story' : 'Chi tiết User Story'} description={editable ? 'Sửa nội dung rồi lưu nháp hoặc gửi QA Manager duyệt.' : 'Nội dung đang chờ QA Manager duyệt nên tạm thời không thể chỉnh sửa.'} className="max-w-3xl">{editable ? <div className="grid gap-4"><div className="grid gap-4 sm:grid-cols-[1fr_150px_110px]"><Field label="Tiêu đề" required><Input value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} /></Field><Field label="Ưu tiên"><Select value={draft.priority} onChange={(event) => setDraft({ ...draft, priority: event.target.value })}>{['Critical', 'High', 'Medium', 'Low'].map((priority) => <option key={priority}>{priority}</option>)}</Select></Field><Field label="Story points"><Input type="number" min="0" max="21" value={draft.storyPoints} onChange={(event) => setDraft({ ...draft, storyPoints: event.target.value })} /></Field></div><Field label="User Story" required><Textarea className="min-h-28" value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} /></Field><Field label="Acceptance Criteria · mỗi dòng một tiêu chí" required><Textarea className="min-h-40" value={draft.acceptanceCriteria} onChange={(event) => setDraft({ ...draft, acceptanceCriteria: event.target.value })} /></Field><div className="flex flex-wrap justify-between gap-2 border-t pt-4 dark:border-slate-800"><Button variant="ghost" onClick={() => setOpen(false)}>Hủy</Button><div className="flex gap-2"><Button variant="outline" disabled={invalid || updateStory.isPending || submitStory.isPending} onClick={() => updateStory.mutate({ id: item._id, body: body() })}>Lưu nháp</Button><Button disabled={invalid || updateStory.isPending || submitStory.isPending} onClick={() => submitStory.mutate({ id: item._id, body: body() })}><Check className="h-4 w-4" />Gửi QA Manager duyệt</Button></div></div></div> : <div><p className="text-sm leading-6 text-slate-600 dark:text-slate-300">{item.description}</p><div className="mt-4 space-y-2 rounded-xl bg-slate-50 p-4 text-sm leading-6 text-slate-600 dark:bg-slate-900 dark:text-slate-300">{(item.acceptanceCriteria || []).map((criterion, index) => <p key={index}>AC {index + 1}: {criterion.criteria}</p>)}</div>{item.approvalStatus === 'PendingApproval' && <p className="mt-4 text-xs text-amber-600">Đã gửi QA Manager; nội dung được khóa trong thời gian chờ duyệt.</p>}</div>}<div className="mt-4 flex justify-end"><Button size="sm" variant="ghost" onClick={() => download(() => e2eApi.exportArtifact('user-story', item._id, 'doc'), `user-story-${item._id}.doc`)}><Download className="h-3.5 w-3.5" />Xuất Word</Button></div></Dialog></>
}
function TestCaseStep({ currentProfile, useCases, currentStories, suites, caseTarget, setCaseTarget, createSuite, generateCases, currentCases, reviewers, user, editCase, submitCase, download }) { if (!currentProfile) return <ProfileRequired />; const change = (key, value) => setCaseTarget({ ...caseTarget, [key]: value }); return <Card className="p-5"><SectionTitle title="Bộ kiểm thử E2E" description="Tạo test case từ hành trình và yêu cầu đã được duyệt." /><div className="mt-5 grid gap-3 rounded-xl bg-slate-50 p-4 md:grid-cols-3 dark:bg-slate-900"><Select value={caseTarget.useCaseId} onChange={(event) => change('useCaseId', event.target.value)}><option value="">Hành trình đã duyệt</option>{(useCases.data || []).filter((item) => item.status === 'Approved').map((item) => <option key={item._id} value={item._id}>{item.name}</option>)}</Select><Select value={caseTarget.storyId} onChange={(event) => change('storyId', event.target.value)}><option value="">Yêu cầu đã duyệt</option>{currentStories.filter((item) => item.approvalStatus === 'Approved').map((item) => <option key={item._id} value={item._id}>{item.title}</option>)}</Select><Select value={caseTarget.suiteId} onChange={(event) => change('suiteId', event.target.value)}><option value="">Test Suite</option>{(suites.data || []).map((item) => <option key={item._id} value={item._id}>{item.name}</option>)}</Select><div className="md:col-span-3 flex flex-wrap gap-2"><Button disabled={!caseTarget.useCaseId || !caseTarget.storyId || !caseTarget.suiteId || generateCases.isPending} onClick={() => generateCases.mutate()}><Sparkles className="h-4 w-4" />Sinh Test Case</Button><Button variant="outline" disabled={createSuite.isPending} onClick={() => createSuite.mutate()}><Plus className="h-4 w-4" />Tạo Test Suite</Button></div></div><div className="mt-5 space-y-4">{currentCases.map((item) => <div key={item._id} className="rounded-xl border p-3"><div className="mb-2 flex justify-end"><Button size="sm" variant="ghost" onClick={() => download(() => e2eApi.exportArtifact('test-case', item._id, 'xls'), `test-case-${item.testCaseId || item._id}.xls`)}><Download className="h-3.5 w-3.5" />Xuất Excel</Button></div><TestCaseCard testCase={item} canApprove={false} canSubmitReview={Boolean(user?.role?.permissions?.includes('testcase:create'))} pendingReview={null} reviewers={reviewers} busy={editCase.isPending || submitCase.isPending} onEdit={(id, body) => editCase.mutateAsync({ id, body })} onSubmitReview={(id, body) => submitCase.mutateAsync({ id, body })} onDecision={() => {}} /></div>)}{!currentCases.length && <p className="py-8 text-center text-sm text-slate-400">Chưa có Test Case trong hành trình này.</p>}</div></Card> }
function PlanStep({ currentCases, plans, suggestPlan, approvePlan, download }) { const items = plans.data || []; return <Card className="p-5"><SectionTitle title="Kế hoạch chạy E2E" description="Tổng hợp các Test Case đã duyệt thành kế hoạch có thể theo dõi." action={<Button size="sm" disabled={!currentCases.some((item) => item.status === 'Approved') || suggestPlan.isPending} onClick={() => suggestPlan.mutate()}><Sparkles className="h-3.5 w-3.5" />Tạo kế hoạch</Button>} /><div className="mt-5 space-y-3">{items.map((item) => <article key={item._id} className="flex flex-col gap-3 rounded-xl border p-4 sm:flex-row sm:items-center sm:justify-between"><div><Badge tone={statusTone[item.approvalStatus] || 'slate'}>{item.approvalStatus || item.status}</Badge><p className="mt-2 text-sm font-semibold">{item.planId ? `${item.planId} · ` : ''}{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.scope}</p></div><div className="flex gap-2">{item.approvalStatus !== 'Approved' && <Button size="sm" onClick={() => approvePlan.mutate(item._id)} disabled={approvePlan.isPending}><Check className="h-3.5 w-3.5" />Duyệt</Button>}<Button size="sm" variant="ghost" onClick={() => download(() => executionApi.exportPlan(item._id, 'doc'), `test-plan-${item.planId || item._id}.doc`)}><Download className="h-3.5 w-3.5" /></Button></div></article>)}{!items.length && <EmptyState title="Chưa có kế hoạch" description="Khi Test Case được duyệt, bạn có thể tạo Test Plan tại đây." />}</div></Card> }
function RunStep({ activeProject, plans }) { const ready = plans.some((item) => item.approvalStatus === 'Approved'); return <Card className="p-5"><div className="mx-auto max-w-xl py-8 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-violet-100 text-violet-600 dark:bg-violet-950 dark:text-violet-300"><PlayCircle className="h-6 w-6" /></span><h2 className="mt-4 text-lg font-semibold">Sẵn sàng chạy hành trình</h2><p className="mt-2 text-sm leading-6 text-slate-500">Sau khi Test Plan được duyệt, chuyển sang Automation Lab để sinh script, chạy E2E và lưu evidence.</p><div className="mt-5 flex justify-center gap-2"><Button disabled={!ready} asChild><Link to={`/automation?project=${activeProject}`}>Mở Automation Lab <ArrowRight className="h-4 w-4" /></Link></Button><Button variant="outline" asChild><Link to={`/reports?project=${activeProject}`}>Xem báo cáo</Link></Button></div>{!ready && <p className="mt-4 text-xs text-amber-600">Cần ít nhất một Test Plan được duyệt để bắt đầu.</p>}</div></Card> }
function GitHubForm({ github, git, setGit, analyzeGithub, activeProject, profile }) {
  const update = (key, value) => setGit({ ...git, [key]: value })
  const [owner, repo] = git.repository.split('/')
  const canReadRepository = Boolean(git.integrationId && owner && repo)
  const repositories = useQuery({ queryKey: ['e2e-github-repositories', git.integrationId], queryFn: () => automationLabApi.githubRepos(git.integrationId), enabled: Boolean(git.integrationId) })
  const branches = useQuery({ queryKey: ['e2e-github-branches', git.integrationId, git.repository], queryFn: () => automationLabApi.githubBranches(git.integrationId, owner, repo), enabled: canReadRepository })
  const commits = useQuery({ queryKey: ['e2e-github-commits', git.integrationId, git.repository, git.ref], queryFn: () => automationLabApi.githubCommits(git.integrationId, owner, repo, git.ref), enabled: Boolean(canReadRepository && git.ref) })
  const pulls = useQuery({ queryKey: ['e2e-github-pulls', git.integrationId, git.repository], queryFn: () => automationLabApi.githubPulls(git.integrationId, owner, repo), enabled: canReadRepository })
  const chooseRepository = (repository) => { const selected = (repositories.data || []).find((item) => item.fullName === repository); setGit({ ...git, repository, ref: selected?.defaultBranch || '', commitSha: '', pullRequestNumber: '' }) }
  const choosePullRequest = (number) => { const selected = (pulls.data || []).find((item) => String(item.number) === number); setGit({ ...git, pullRequestNumber: number, ref: selected?.headRef || git.ref, commitSha: selected?.headSha || '' }) }
  return <div className="space-y-3"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><Field label="1. GitHub connection"><Select value={git.integrationId} onChange={(event) => setGit({ ...git, integrationId: event.target.value, repository: '', ref: '', commitSha: '', pullRequestNumber: '' })}><option value="">Chọn GitHub connection</option>{github.map((item) => <option key={item._id} value={item._id}>{item.displayName}</option>)}</Select></Field><Field label="2. Repository"><Select value={git.repository} disabled={!git.integrationId || repositories.isPending} onChange={(event) => chooseRepository(event.target.value)}><option value="">{repositories.isPending ? 'Đang tải repository…' : 'Chọn repository'}</option>{(repositories.data || []).map((item) => <option key={item.id} value={item.fullName}>{item.fullName}{item.private ? ' · private' : ''}</option>)}</Select></Field><Field label="3. Branch"><Select value={git.ref} disabled={!git.repository || branches.isPending} onChange={(event) => setGit({ ...git, ref: event.target.value, commitSha: '', pullRequestNumber: '' })}><option value="">{branches.isPending ? 'Đang tải branch…' : 'Chọn branch'}</option>{(branches.data || []).map((item) => <option key={item.sha} value={item.name}>{item.name}</option>)}</Select></Field><Field label="Commit (tùy chọn)"><Select value={git.commitSha} disabled={!git.ref || commits.isPending} onChange={(event) => setGit({ ...git, commitSha: event.target.value, pullRequestNumber: '' })}><option value="">Commit mới nhất của branch</option>{(commits.data || []).map((item) => <option key={item.sha} value={item.sha}>{item.sha.slice(0, 8)} · {item.message.split('\n')[0]}</option>)}</Select></Field><Field label="Pull Request (tùy chọn)"><Select value={String(git.pullRequestNumber || '')} disabled={!git.repository || pulls.isPending} onChange={(event) => choosePullRequest(event.target.value)}><option value="">Không chọn Pull Request</option>{(pulls.data || []).map((item) => <option key={item.number} value={item.number}>#{item.number} · {item.title}</option>)}</Select></Field><Field label="Tệp được phép phân tích"><Textarea className="min-h-20 font-mono text-xs" value={git.paths} onChange={(event) => update('paths', event.target.value)} placeholder="README.md\nsrc/routes/orders.js" /></Field></div>{(repositories.isError || branches.isError || commits.isError || pulls.isError) && <p className="rounded-lg bg-rose-50 p-3 text-xs text-rose-700 dark:bg-rose-950/30 dark:text-rose-200">Không tải được dữ liệu GitHub. Kiểm tra connection và quyền truy cập repository.</p>}<p className="rounded-lg bg-amber-50 p-3 text-xs text-amber-900 dark:bg-amber-950/30 dark:text-amber-100">Chỉ các tệp được liệt kê mới được đọc và gửi tới AI. Commit hoặc Pull Request được chọn sẽ được lưu vào System Specification để bảo đảm truy vết.</p><Button disabled={!activeProject || !profile.name || !git.integrationId || !git.repository || !git.ref || !lines(git.paths).length || analyzeGithub.isPending} onClick={() => analyzeGithub.mutate()}><FileCode2 className="h-4 w-4" />{analyzeGithub.isPending ? 'Đang phân tích…' : 'Tạo System Specification'}</Button></div>
}
function ProfileRequired({ profiles, selectProfile }) { return <EmptyState title="Chọn một System Profile trước" description="Profile giữ ngữ cảnh, môi trường và quyền truy cập cho toàn bộ luồng E2E." action={profiles?.data?.length ? <Select value="" onChange={(event) => selectProfile?.(event.target.value)}><option value="">Chọn System Profile</option>{profiles.data.map((item) => <option key={item._id} value={item._id}>{item.name}</option>)}</Select> : null} /> }
function ContextCard({ profile, label, items }) { return <Card className="h-fit p-5"><p className="text-xs font-semibold uppercase tracking-wider text-violet-600 dark:text-violet-400">{label}</p><p className="mt-2 text-sm font-semibold">{profile.name}</p><p className="mt-1 text-xs text-slate-500">{profile.baseUrl || 'Chưa đặt Base URL'}</p><dl className="mt-5 divide-y">{items.map(([name, value]) => <div key={name} className="flex items-center justify-between py-3 text-sm"><dt className="text-slate-500">{name}</dt><dd className="font-semibold">{value}</dd></div>)}</dl></Card> }
function ModeOption({ active, disabled, icon: Icon, title, description, onClick }) { return <button type="button" disabled={disabled} onClick={onClick} className={`rounded-xl border p-4 text-left transition ${active ? 'border-violet-500 bg-violet-50 ring-1 ring-violet-500 dark:bg-violet-950/30' : 'hover:border-slate-300'} disabled:cursor-not-allowed disabled:opacity-60`}><Icon className="h-4 w-4 text-violet-600" /><p className="mt-3 text-sm font-semibold">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{description}</p></button> }
function Field({ label, required, children }) { return <label className="block"><span className="label">{label}{required && <b className="text-danger"> *</b>}</span>{children}</label> }
